function profileLevels(data,i){if(!data||!Number.isFinite(data.elevation))return [];const levels=[];for(const p of airLevels){const d={p,levelIndex:airLevels.indexOf(p)};for(const f of airFields)d[f]=data.hourly[f+'_'+p+'hPa']?.[i];if(airFields.some(k=>!Number.isFinite(d[k]))||d.geopotential_height<=data.elevation)continue;const a=d.wind_direction*Math.PI/180;d.u=-d.wind_speed*Math.sin(a);d.v=-d.wind_speed*Math.cos(a);levels.push(d)}return levels.sort((a,b)=>a.geopotential_height-b.geopotential_height)}
