$('airForm').onsubmit=async e=>{e.preventDefault();const la=Number($('airLat').value),lo=Number($('airLon').value);if(!$('airLat').value.trim()||!$('airLon').value.trim()||!Number.isFinite(la)||!Number.isFinite(lo)||Math.abs(la)>90||Math.abs(lo)>180){$('airStatus').textContent='Enter a valid latitude and longitude.';return}const token=++airRequest;airController?.abort();airController=new AbortController();const controller=airController,timeout=setTimeout(()=>controller.abort(),45000);$('loadAir').disabled=true;$('airStatus').textContent='Loading real pressure-level forecasts…';const hourly=airLevels.flatMap(p=>airFields.map(f=>f+'_'+p+'hPa')).join(','),url='https://api.open-meteo.com/v1/forecast?latitude='+la+'&longitude='+lo+'&hourly='+hourly+'&forecast_days=16&wind_speed_unit=ms&timezone=GMT&elevation=nan&cell_selection=nearest&models=gfs_global';try{const r=await fetch(url,{signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(token!==airRequest)return;if(!validAir(d,[la,lo]))throw Error('Invalid atmospheric response');airRetrieved=new Date().toISOString();airIsSnapshot=false;airRequestedCoordinate=[la,lo];setAir(d)}catch{if(token===airRequest)$('airStatus').textContent='Could not load this column. The previously loaded coordinates and profile remain visible; try again later.'}finally{clearTimeout(timeout);if(token===airRequest){airController=null;$('loadAir').disabled=false}}};
